	}()

	start := time.Now()
	select {
	case rerr := <-doneCh:
		res.RestartReturned = true
		if rerr != nil {
			res.RestartError = rerr.Error()
		}
	case <-time.After(caRestartWait):
		res.RestartFrames = caBlockedReplayFrames()
	}
