		Peers:              1,
		Bootstrap:          true,
		Conf:               conf,
		CommitTrackingLogs: true,
	})

	leader := c.Leader()

	applyN := func(n int) {
		t.Helper()
		var last Future
		for i := 0; i < n; i++ {
			last = leader.Apply([]byte(fmt.Sprintf("test%d", i)), 0)
		}
		if err := last.Error(); err != nil {
			t.Fatalf("%s: apply %d: %v", tc.name, n, err)
		}
	}

