		joined := strings.Join(block, "\n")
		if strings.Contains(joined, "processLogs") && strings.Contains(joined, "restoreFromCommittedLogs") {
			for _, f := range block {
				if strings.HasPrefix(f, "goroutine ") || strings.Contains(f, ".go:") {
					frames = append(frames, f)
					if len(frames) >= 10 {
						break
					}
				}
			}
			break
		}
	}
	return frames
}

