		MaxAppendEntries:       prefix.MaxAppendEntries,
		FSMBufferCapacity:      prefix.FSMBufferCapacity,
		ReplayWindow:           prefix.ReplayWindow,
		FSMBoundInWindow:       prefix.FSMBoundInWindow,
